    // END MACHINE VECTORS
    public static int run()throws Exception{
        assertions=0;check(VECTORS.length>0,"Native effects vectors present");Owner last=null;
        for(String vector:VECTORS){DataInputStream in=new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(vector))));String name=in.readUTF();boolean pixels=in.readBoolean();int loadHandle=in.readInt();Map<Integer,int[][]> writes=new HashMap<>();for(int n=in.readInt();n>0;n--){int mask=in.readInt();int[][] w=new int[in.readInt()][];for(int k=0;k<w.length;k++)w[k]=ints(in);writes.put(mask,w);}Owner owner=new Owner(snapshot(in),pixels,loadHandle,writes);last=owner;String error=null;for(int n=in.readInt();n>0;n--){String kind=in.readUTF();int[] a=ints(in);if(error==null)try{owner.operation(kind,a);}catch(IOException failure){error=failure.getMessage();}}Snapshot expected=snapshot(in);String nativeError=in.readUTF();check(nativeError.isEmpty()?error==null:error!=null,"Exact native known owner boundary "+name+" "+error);owner.compare(expected,name);}
        final byte[] settings=new byte[Pc1NativeSettings.SIZE];Pc1NativeFrame frame=Pc1NativeFrame.zeroBss();Pc1NativeMemory raw=new Pc1NativeMemory(frame,Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){public int read(int at){return settings[at]&255;}public void write(int at,int value){settings[at]=(byte)value;}});Pc1Effects.Memory m=new Pc1Effects.Memory(raw);check(m.readInt(Pc1Effects.SPRITE_HANDLE)==-1&&m.readInt(Pc1Effects.RAIN_HANDLE)==-1,"PE handles minus one");check(m.readInt(Pc1Effects.PARTICLES)==0&&m.readInt(Pc1Effects.RECT_COUNT)==0,"PE BSS zero");m.writeInt(Pc1Effects.PARTICLES+4996,0x89abcdef);m.writeInt(Pc1Effects.RECT_BANK,1);m.writeInt(Pc1Effects.KIND,3);ByteArrayOutputStream out=new ByteArrayOutputStream();m.save(new DataOutputStream(out));check(out.size()==4+5000+5308+8,"P1V1 exact owned bytes");Pc1Effects.Memory.Image image=Pc1Effects.Memory.load(new DataInputStream(new ByteArrayInputStream(out.toByteArray())));m.writeInt(Pc1Effects.PARTICLES+4996,0);m.writeInt(Pc1Effects.KIND,2);m.restore(image);check(m.readInt(Pc1Effects.PARTICLES+4996)==0x89abcdef,"Codec preserves stale suffix");check(m.readInt(Pc1Effects.KIND)==2,"Codec does not roll back borrowed frame");
        Pc1Effects missing=new Pc1Effects(last,last.compositor,null,null);last.writeInt(Pc1Effects.PENDING,1);missing.drawLayer(1);missing.update();check(true,"Gated effects require no unused services");last.writeInt(Pc1Effects.PENDING,0);boolean rejected=false;try{missing.initialize(1,1);}catch(IOException failure){rejected=true;}check(rejected,"Missing live resource/RNG precisely fails");return assertions;
    }
